function openLevels(){const modal=$('#modalContent');modal.innerHTML=`<div class="eyebrow">Choose your quiet place</div><h2>Three gardens to wander</h2><p>Each layout is gently arranged so a matching path is always there.</p><div class="level-list">${LEVELS.map((l,i)=>`<button class="level-card ${i===levelIndex?'current':''}" data-level="${i}"><b>${l.short}</b><span>${l.mood}</span></button>`).join('')}</div><button class="tool-btn modal-close" id="modalClose">Return to the garden</button>`;$('#modalBackdrop').classList.add('open');modal.querySelectorAll('[data-level]').forEach(btn=>btn.addEventListener('click',()=>{$('#modalBackdrop').classList.remove('open');setupLevel(Number(btn.dataset.level));notify(`${LEVELS[levelIndex].name}, freshly laid.`)}));$('#modalClose').onclick=()=>$('#modalBackdrop').classList.remove('open')}
function showWin(){const modal=$('#modalContent');modal.innerHTML=`<div class="win-mark">✿</div><div class="eyebrow">The garden is at rest</div><h2>Beautifully done.</h2><p>You found every pair in ${$('#timeStat').textContent}. Take this quiet with you.</p><button class="tool-btn" id="nextLevel">${levelIndex<LEVELS.length-1?'Wander to the next garden':'Visit the first garden again'}　→</button><div><button class="tool-btn modal-close" id="closeWin">Stay a little longer</button></div>`;$('#modalBackdrop').classList.add('open');$('#nextLevel').onclick=()=>{$('#modalBackdrop').classList.remove('open');setupLevel((levelIndex+1)%LEVELS.length)};$('#closeWin').onclick=()=>$('#modalBackdrop').classList.remove('open')}
function showRules(){const modal=$('#modalContent');modal.innerHTML=`<div class="eyebrow">A small guide</div><h2>How to play</h2><p class="rules">Find two matching tiles and tap them to let them drift away. A tile is free when there is no tile resting above it and at least one of its long sides is open. Use <b>Hint</b> whenever you need a gentle nudge. Every garden has a guaranteed path to completion.</p><button class="tool-btn" id="rulesClose">Begin again</button>`;$('#modalBackdrop').classList.add('open');$('#rulesClose').onclick=()=>$('#modalBackdrop').classList.remove('open')}
function ensureAudio(){if(!audioCtx){const Ctx=window.AudioContext||window.webkitAudioContext;if(Ctx)audioCtx=new Ctx()}if(audioCtx?.state==='suspended')audioCtx.resume()}
function playTone(freq,duration=.16,type='sine',volume=.035){if(!sfxOn)return;ensureAudio();if(!audioCtx)return;const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(volume,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration)}
function playMatch(){if(!sfxOn)return;playTone(540,.17,'sine',.04);setTimeout(()=>playTone(720,.22,'sine',.027),95)}
function startMusic(){ensureAudio();if(!audioCtx)return;musicOn=true;$('#musicBtn').classList.add('current');$('#musicBtn').style.background='#eaf0e8';const notes=[261.63,329.63,392,329.63,293.66,349.23,440,349.23];const play=()=>{if(!musicOn)return;const now=audioCtx.currentTime;const osc=audioCtx.createOscillator(),gain=audioCtx.createGain(),filter=audioCtx.createBiquadFilter();osc.type='sine';osc.frequency.value=notes[musicStep%notes.length];filter.type='lowpass';filter.frequency.value=700;gain.gain.setValueAtTime(.0001,now);gain.gain.linearRampToValueAtTime(.012,now+1.6);gain.gain.exponentialRampToValueAtTime(.0001,now+5.4);osc.connect(filter);filter.connect(gain);gain.connect(audioCtx.destination);osc.start(now);osc.stop(now+5.5);musicStep++;musicTimer=setTimeout(play,3900)};play()}
function stopMusic(){musicOn=false;clearTimeout(musicTimer);$('#musicBtn').classList.remove('current');$('#musicBtn').style.background=''}
$('#hintBtn').addEventListener('click',hint);$('#undoBtn').addEventListener('click',undo);$('#restartBtn').addEventListener('click',restart);$('#levelsBtn').addEventListener('click',openLevels);$('#musicBtn').addEventListener('click',()=>{ensureAudio();if(musicOn)stopMusic();else startMusic()});$('#soundBtn').addEventListener('click',()=>{sfxOn=!sfxOn;$('#soundBtn').style.opacity=sfxOn?'1':'.48';if(sfxOn){ensureAudio();playTone(580)}});$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))$('#modalBackdrop').classList.remove('open')});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modalBackdrop').classList.remove('open');if(e.key.toLowerCase()==='h')hint();if(e.key.toLowerCase()==='u')undo()});
setupLevel(0);setTimeout(()=>{if(!localStorage.getItem('stillwater-intro')){showRules();localStorage.setItem('stillwater-intro','seen')}},500);
</script>
</body>
</html>

